#!/usr/bin/env node
/**
 * generate-headers.js
 *
 * Generates unified ffi.h and fficonfig.h from libffi sources and templates.
 * Run this script after updating third-party/libffi to regenerate the headers.
 *
 * Usage: npm run generate-ffi-headers
 *
 * Templates:
 *   - ffi.h.in      → from libffi/include/ffi.h.in (upstream)
 *   - fficonfig.h.in → from this directory (custom)
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const LIBFFI_DIR = path.join(__dirname, "..", "libffi");
const TEMPLATE_DIR = __dirname;
const OUTPUT_DIR = path.join(__dirname, "fficonfig");

/** A text file with LF line endings, whatever the checkout (core.autocrlf on Windows). */
function readText(file) {
  return fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n");
}

/** Replace `pattern` in `text`; throw when it is not there, instead of silently generating another header. */
function replaceRequired(text, pattern, replacement, what) {
  const found = typeof pattern === "string" ? text.includes(pattern) : new RegExp(pattern.source, pattern.flags.replace("g", "")).test(text);
  if (!found) throw new Error(`generate-headers: ${what} not found in the template`);
  return text.replace(pattern, replacement);
}

/**
 * Extract version info from configure.ac.
 *
 * The release version comes from AC_INIT(...), which is the single source of
 * truth (it drives autotools' @VERSION@). The FFI_VERSION_STRING /
 * FFI_VERSION_NUMBER literal assignments are cross-checked and a warning is
 * emitted if they drift, because upstream has at times forgotten to bump them in lockstep with
 * AC_INIT (e.g. libffi 3.6.0 still declares FFI_VERSION_STRING="3.5.2").
 */
function extractVersion() {
  const configureAc = readText(path.join(LIBFFI_DIR, "configure.ac"));

  // Primary source of truth: AC_INIT([libffi],[X.Y.Z],...)
  const acInitMatch = configureAc.match(/AC_INIT\(\s*\[libffi\]\s*,\s*\[([^\]]+)\]/);
  if (!acInitMatch) {
    throw new Error("Could not extract version from AC_INIT in configure.ac");
  }
  const string = acInitMatch[1].trim();

  // Derive the numeric form (x * 10000 + y * 100 + z) from the release version.
  const parts = string.split(".").map((n) => parseInt(n, 10));
  if (parts.length < 3 || parts.some((n) => Number.isNaN(n))) {
    throw new Error(`Unexpected libffi version format: "${string}"`);
  }
  const [major, minor, patch] = parts;
  const number = major * 10000 + minor * 100 + patch;

  // Cross-check against the FFI_VERSION_* lines and warn on drift.
  const versionStringMatch = configureAc.match(/FFI_VERSION_STRING="([^"]+)"/);
  const versionNumberMatch = configureAc.match(/FFI_VERSION_NUMBER=(\d+)/);
  // m4 expands AC_PACKAGE_VERSION from AC_INIT; it is not a conflicting literal.
  if (versionStringMatch && versionStringMatch[1] !== "AC_PACKAGE_VERSION" && versionStringMatch[1] !== string) {
    console.warn(`Warning: FFI_VERSION_STRING="${versionStringMatch[1]}" disagrees with AC_INIT "${string}"; using AC_INIT.`);
  }
  if (versionNumberMatch && parseInt(versionNumberMatch[1], 10) !== number) {
    console.warn(`Warning: FFI_VERSION_NUMBER=${versionNumberMatch[1]} disagrees with derived ${number}; using ${number}.`);
  }

  return { string, number };
}

/**
 * Generate fficonfig.h from template
 */
function generateFficonfig(version) {
  let output = readText(path.join(TEMPLATE_DIR, "fficonfig.h.in"));
  output = replaceRequired(output, /@VERSION@/g, version.string, "@VERSION@");

  // Define FFI_MMAP_EXEC_WRIT for macOS x64
  output = replaceRequired(
    output,
    "/* No mmap exec workarounds needed */\n/* #undef FFI_MMAP_EXEC_WRIT */\n/* #undef FFI_MMAP_EXEC_EMUTRAMP_PAX */",
    "/* mmap exec workaround needed on macOS x64 */\n#if defined(FFI_PLATFORM_MACOS) && defined(FFI_ARCH_X86_64)\n#  define FFI_MMAP_EXEC_WRIT 1\n#endif\n\n/* No mmap exec workarounds needed */\n/* #undef FFI_MMAP_EXEC_WRIT */\n/* #undef FFI_MMAP_EXEC_EMUTRAMP_PAX */",
    "the mmap exec workarounds block",
  );

  return output;
}

/**
 * Generate ffi.h from libffi's ffi.h.in template
 */
function generateFfiH(version) {
  let template = readText(path.join(LIBFFI_DIR, "include", "ffi.h.in"));

  // Platform detection to insert
  const platformDetection = `/* ============================================================================
 * Platform/Architecture Detection and Target Definition
 * ============================================================================
 *
 * AUTO-GENERATED FILE - DO NOT EDIT MANUALLY
 * Generated by: third-party/libffi_cmake/generate-headers.js
 * From libffi version: ${version.string}
 *
 * ============================================================================
 */

/* Detect architecture and define target */
#if defined(__x86_64__) || defined(_M_X64) || defined(__amd64__)
#  if defined(_WIN32) || defined(_WIN64)
#    ifndef X86_WIN64
#      define X86_WIN64
#    endif
#  else
#    ifndef X86_64
#      define X86_64
#    endif
#  endif
#elif defined(__aarch64__) || defined(_M_ARM64)
#  ifndef AARCH64
#    define AARCH64
#  endif
#elif defined(__arm__) || defined(_M_ARM)
#  ifndef ARM
#    define ARM
#  endif
#elif defined(__i386__) || defined(_M_IX86)
#  if defined(_WIN32)
#    ifndef X86_WIN32
#      define X86_WIN32
#    endif
#  else
#    ifndef X86
#      define X86
#    endif
#  endif
#endif`;

  // ffitarget include logic
  const ffitargetInclude = `/* Include the appropriate ffitarget.h based on architecture */
#if defined(X86_WIN64) || defined(X86_64) || defined(X86_WIN32) || defined(X86)
#  include "x86/ffitarget.h"
#elif defined(AARCH64)
#  include "aarch64/ffitarget.h"
#elif defined(ARM)
#  include "arm/ffitarget.h"
#else
#  error "Unsupported architecture for libffi"
#endif`;

  let output = template;

  // Update version in copyright header
  output = output.replace(/libffi @VERSION@/g, `libffi ${version.string}`);

  // Replace @TARGET@ block with platform detection
  output = replaceRequired(output, /\/\* Specify which architecture libffi is configured for\. \*\/\s*#ifndef @TARGET@\s*#define @TARGET@\s*#endif/, platformDetection, "the @TARGET@ block");

  // Replace @HAVE_LONG_DOUBLE@ with configure's rule, a long double larger than
  // a double, from the compiler's predefined macros (ffi.h is also included by
  // the assembly sources, so no <float.h>). Equal on macOS ARM64 and with MSVC
  // (which defines neither macro): FFI_TYPE_LONGDOUBLE is then FFI_TYPE_DOUBLE.
  output = replaceRequired(output, /#if @HAVE_LONG_DOUBLE@/g, "#if defined(__LDBL_MANT_DIG__) && defined(__DBL_MANT_DIG__) && __LDBL_MANT_DIG__ > __DBL_MANT_DIG__", "#if @HAVE_LONG_DOUBLE@");

  // Replace @FFI_EXEC_TRAMPOLINE_TABLE@ with the condition fficonfig.h uses
  // (macOS ARM64), not with its macro: ffi.h does not include fficonfig.h, and
  // node-ctypes and some libffi sources (types.c, prep_cif.c) include ffi.h
  // first, so they would see another ffi_closure layout (48 bytes, not 40).
  output = replaceRequired(output, /#if @FFI_EXEC_TRAMPOLINE_TABLE@/g, "#if defined(__APPLE__) && defined(__MACH__) && defined(AARCH64)", "#if @FFI_EXEC_TRAMPOLINE_TABLE@");

  // Replace version placeholders
  output = replaceRequired(output, /@FFI_VERSION_STRING@/g, version.string, "@FFI_VERSION_STRING@");
  output = replaceRequired(output, /@FFI_VERSION_NUMBER@/g, version.number.toString(), "@FFI_VERSION_NUMBER@");

  // Replace #include <ffitarget.h> with our conditional include
  output = replaceRequired(output, /#include <ffitarget\.h>/, ffitargetInclude, "#include <ffitarget.h>");

  // Wrap __attribute__((deprecated)) for MSVC compatibility
  output = output.replace(/(\s+)__attribute__\(\(deprecated\)\);/g, "\n#if defined(__GNUC__)\n  __attribute__((deprecated))\n#endif\n  ;");

  return output;
}

/**
 * Main
 */
function main() {
  console.log("Generating libffi headers for node-ctypes...\n");

  // Check if libffi sources exist
  if (!fs.existsSync(path.join(LIBFFI_DIR, "configure.ac"))) {
    console.error("Error: libffi sources not found at", LIBFFI_DIR);
    console.error("Please ensure third-party/libffi contains the libffi source code.");
    console.error("Run: git submodule update --init");
    process.exit(1);
  }

  // Check if template exists
  if (!fs.existsSync(path.join(TEMPLATE_DIR, "fficonfig.h.in"))) {
    console.error("Error: fficonfig.h.in template not found at", TEMPLATE_DIR);
    process.exit(1);
  }

  // Extract version
  const version = extractVersion();
  console.log(`libffi version: ${version.string} (${version.number})`);

  // Ensure output directory exists
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  // Generate fficonfig.h
  const fficonfig = generateFficonfig(version);
  const fficonfigPath = path.join(OUTPUT_DIR, "fficonfig.h");
  fs.writeFileSync(fficonfigPath, fficonfig);
  console.log(`Generated: ${fficonfigPath}`);

  // Generate ffi.h
  const ffiH = generateFfiH(version);
  const ffiHPath = path.join(OUTPUT_DIR, "ffi.h");
  fs.writeFileSync(ffiHPath, ffiH);
  console.log(`Generated: ${ffiHPath}`);

  console.log("\nDone! Headers generated successfully.");
  console.log('Run "npm run rebuild" to rebuild with the new headers.');
}

main();
